import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { api, errMsg } from '../../lib/api';
import { EmptyState, Spinner } from '../ui';
import { fmtDate, fmtNum } from '../../lib/format';

interface AItem {
  id: string; srNo?: string; itemName: string; category?: string;
  quantity?: number | null; unit?: string;
  specifications?: string; requirements?: string; dependencies?: string; notes?: string;
}

// The AI-processed "bible" — a clean, actionable procurement breakdown of the
// raw BOQ. Generated by AI; the raw BOQ table is left untouched.
export default function BOQAnalysisView({ projectId, isAdmin }: { projectId: string; isAdmin: boolean }) {
  const qc = useQueryClient();
  const [err, setErr] = useState('');
  const [query, setQuery] = useState('');

  const { data, isLoading } = useQuery({
    queryKey: ['boq-analysis', projectId],
    queryFn: async () => (await api.get(`/projects/${projectId}/boq/analysis`)).data as { items: AItem[]; analyzedAt: string | null; aiEnabled: boolean },
  });

  const analyze = useMutation({
    mutationFn: () => api.post(`/projects/${projectId}/boq/analyze`, {}),
    onSuccess: () => { setErr(''); qc.invalidateQueries({ queryKey: ['boq-analysis', projectId] }); },
    onError: (e) => setErr(errMsg(e)),
  });

  if (isLoading) return <Spinner label="Loading analysis…" />;
  const items = data?.items ?? [];

  const filtered = query.trim()
    ? items.filter((i) => `${i.itemName} ${i.category} ${i.specifications} ${i.requirements} ${i.notes}`.toLowerCase().includes(query.toLowerCase()))
    : items;

  const grouped: { category: string; rows: AItem[] }[] = [];
  for (const it of filtered) {
    const cat = it.category || 'Other';
    let g = grouped.find((x) => x.category === cat);
    if (!g) { g = { category: cat, rows: [] }; grouped.push(g); }
    g.rows.push(it);
  }

  return (
    <div className="space-y-3">
      <div className="flex flex-wrap items-center justify-between gap-2">
        <div>
          <div className="text-sm font-medium text-slate-700">AI Procurement Breakdown <span className="ml-1 rounded bg-navy/10 px-1.5 py-0.5 text-xs font-semibold text-navy">BIBLE</span></div>
          <div className="text-xs text-slate-400">
            {data?.analyzedAt ? `${items.length} structured items · generated ${fmtDate(data.analyzedAt)}` : 'Not generated yet'}
          </div>
        </div>
        <div className="flex items-center gap-2">
          {items.length > 0 && (
            <input className="input w-48 text-sm" placeholder="Search specs, items…" value={query} onChange={(e) => setQuery(e.target.value)} />
          )}
          {isAdmin && (
            <button className="btn-primary text-sm" disabled={analyze.isPending || data?.aiEnabled === false} onClick={() => analyze.mutate()}>
              {analyze.isPending ? 'Analyzing…' : items.length ? '↻ Regenerate' : '🤖 Generate Analysis'}
            </button>
          )}
        </div>
      </div>

      {err && <div className="rounded-lg bg-red-50 px-3 py-2 text-sm text-red-700">{err}</div>}
      {data?.aiEnabled === false && <div className="rounded-lg bg-amber-50 px-3 py-2 text-sm text-amber-700">AI is not configured. Set GROQ_API_KEY in server/.env to enable analysis.</div>}

      {items.length === 0 ? (
        <EmptyState
          title="No AI analysis yet"
          hint={isAdmin ? 'Generate a clean, structured procurement breakdown of the raw BOQ — the AI extracts the key specs, requirements, dependencies and notes for each item, leaving the raw BOQ untouched.' : 'The project admin has not generated the AI breakdown yet.'}
          action={isAdmin ? <button className="btn-primary mt-2" disabled={analyze.isPending} onClick={() => analyze.mutate()}>🤖 Generate Analysis</button> : undefined}
        />
      ) : (
        <div className="space-y-4">
          {grouped.map((g) => (
            <div key={g.category}>
              <div className="mb-2 text-xs font-semibold uppercase tracking-wide text-slate-400">{g.category} <span className="text-slate-300">({g.rows.length})</span></div>
              <div className="space-y-2">
                {g.rows.map((it) => <AnalysisCard key={it.id} item={it} />)}
              </div>
            </div>
          ))}
          {filtered.length === 0 && <div className="py-8 text-center text-sm text-slate-400">No items match “{query}”.</div>}
        </div>
      )}
    </div>
  );
}

function AnalysisCard({ item }: { item: AItem }) {
  return (
    <div className="card p-4">
      <div className="flex items-start justify-between gap-3">
        <div className="min-w-0">
          <div className="font-semibold text-navy">{item.itemName}</div>
          {item.srNo && <div className="text-xs text-slate-400">Sr. {item.srNo}</div>}
        </div>
        {item.quantity != null && (
          <div className="whitespace-nowrap rounded-lg bg-navy/5 px-3 py-1 text-sm font-semibold text-navy">{fmtNum(item.quantity)} {item.unit}</div>
        )}
      </div>
      <div className="mt-3 grid gap-3 sm:grid-cols-2">
        <Field label="Specifications" value={item.specifications} accent="text-slate-700" />
        <Field label="Requirements" value={item.requirements} accent="text-blue-700" />
        <Field label="Dependencies" value={item.dependencies} accent="text-purple-700" />
        <Field label="Notes" value={item.notes} accent="text-amber-700" />
      </div>
    </div>
  );
}

function Field({ label, value, accent }: { label: string; value?: string; accent: string }) {
  if (!value) return null;
  // Split "; "-separated specs into bullets for readability.
  const parts = value.split(/;\s*/).map((s) => s.trim()).filter(Boolean);
  return (
    <div className="rounded-lg bg-slate-50 p-2.5">
      <div className={`mb-1 text-[11px] font-semibold uppercase tracking-wide ${accent}`}>{label}</div>
      {parts.length > 1 ? (
        <ul className="list-inside list-disc space-y-0.5 text-xs text-slate-600">
          {parts.map((p, i) => <li key={i}>{p}</li>)}
        </ul>
      ) : (
        <div className="text-xs text-slate-600">{value}</div>
      )}
    </div>
  );
}
